export const microFuer = (gebiet, stufe) => MICROCASES.filter((m) => m.gebiet === gebiet && m.stufe === stufe);
export const klausurenFuer = (gebiet, stufe) => KLAUSUREN.filter((k) => k.gebiet === gebiet && k.stufe === stufe);
export const klausurFinden = (id) => KLAUSUREN.find((k) => k.id === id) || null;

/* Ein Übungsfall unter 150 Wörtern ist in der Sache ein langer Microcase –
   die Kennzeichnung hilft beim Zeitbudget der Lernsitzung. */
export const fallklasse = (fall) => (fall.woerter < 150 ? "kurz" : "uebung");
